    Project p;p.tracks.resize(6);const char*names[]={"Drums","Sub bass","Chords","Lead","Vocal","Pad"};for(int id=0;id<6;id++){auto&t=p.tracks[id];t.name=names[id];t.midiChannel=1;t.notes={{0,.5,60,.8f}};t.patternLength=4;t.clips={{0,4}};t.patterns={{"B",8,{{0,1,72,.7f}}}};}p.tracks[4].clips={{4,4},{12,2}};p.tracks[5].frozen=true;
