    ArrangeOptions defaults;check(!defaults.append,"new arrangements replace participating track clips by default");candidate=p;candidate.bars=256;candidate.markers={{0,"Renamed old intro",1},{1000,"Old ending",3}};candidate.loopStart=900;candidate.loopEnd=1000;auto firstPlan=buildArrangement(candidate,defaults);applyArrangement(candidate,firstPlan);check(candidate.markers.size()==8&&candidate.markers.front().name=="Intro"&&candidate.bars==64&&candidate.loopStart==0&&candidate.loopEnd==0,"replacement removes all old markers including renamed and distant markers and resets obsolete range");auto replacement=buildArrangement(candidate,defaults);applyArrangement(candidate,replacement);check(candidate.markers.size()==8&&candidate.tracks[4].clips.size()==2,"repeated replacement does not accumulate clips or markers");
    defaults.bars=32;applyArrangement(candidate,buildArrangement(candidate,defaults));check(candidate.bars==32&&candidate.markers.size()==8&&candidate.markers.back().beat<128,"shorter arrangement removes the old ending");defaults.append=true;auto appendPlan=buildArrangement(candidate,defaults);applyArrangement(candidate,appendPlan);check(candidate.markers.size()==8&&candidate.markers.front().beat==appendPlan.start,"explicit append keeps clips but replaces the section map");
    std::set<std::wstring>genres;std::set<std::vector<int>>profiles;for(int style=0;style<(int)arrangeStyles().size();style++){genres.insert(arrangeStyle(style).name);std::vector<int>signature;for(int bars:{32,33,64,96,128,192,256,384,512}){defaults.style=style;defaults.bars=bars;defaults.append=false;auto sections=defaultArrangeSections(defaults);int total=0;for(auto&s:sections){check(s.bars>=4&&s.energy>=0&&s.energy<=100,"genre sections remain valid");total+=s.bars;if(bars==128){signature.push_back(s.bars);signature.push_back(s.energy);}}check(total==bars,"each genre keeps the exact requested length");auto preview=buildArrangement(p,defaults);check(preview.start==0&&preview.length==bars*4.&&!preview.clips.empty(),"all genre plans can be built");for(auto&c:preview.clips)check(c.clip.beat>=0&&c.clip.beat+c.clip.length<=preview.length,"genre placements stay within the song");}profiles.insert(signature);}check(genres.size()==20&&profiles.size()==20,"twenty distinct genre structures and energy profiles");check(arrangeStyle(-1).name==arrangeStyles().front().name&&arrangeStyle(999).name==arrangeStyles().back().name,"invalid genre choices are bounded");
